<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),visible=ref(false),editing=ref<any>();const blank=()=>({channelCode:'',channelName:'',contactName:'',contactPhone:'',settlementInfo:'',status:'ENABLED'});const form=reactive<any>(blank());async function load(){try{rows.value=await api.channels()as any[]}catch(e:any){ElMessage.error(e.message)}}function open(row?:any){editing.value=row;Object.assign(form,blank(),row||{});visible.value=true}async function save(){try{editing.value?await api.updateChannel(editing.value.id,form):await api.createChannel(form);ElMessage.success('渠道档案已保存');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>二级渠道档案</h1><p>维护渠道联系人和结算基础信息，不开放渠道独立账号。</p></div><el-button type="primary" @click="open()">新增渠道</el-button></div><div class="table-card"><el-table :data="rows"><el-table-column prop="channelCode" label="渠道编码" min-width="140"/><el-table-column prop="channelName" label="渠道名称" min-width="170"/><el-table-column prop="contactName" label="联系人" width="110"/><el-table-column prop="contactPhone" label="联系方式" min-width="140"/><el-table-column prop="settlementInfo" label="结算信息" min-width="220"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="createdAt" label="创建时间" min-width="170"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑渠道':'新增渠道'" width="620"><el-form label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="渠道编码"><el-input v-model="form.channelCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="渠道名称"><el-input v-model="form.channelName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系方式"><el-input v-model="form.contactPhone"/></el-form-item></el-col><el-col :span="24"><el-form-item label="结算信息"><el-input v-model="form.settlementInfo" type="textarea"/></el-form-item></el-col><el-col :span="12"><el-form-item label="状态"><el-select v-model="form.status" style="width:100%"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></div></template></el-dialog></div></template>

